return ['domain'=>'blockstudio','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'bho','project-id-version'=>'Blockstudio','po-revision-date'=>'2026-10-23 15:26+0000','messages'=>['Blockstudio'=>'Blockstudio','The "%1$s" attribute on a %2$s block tag is dropped because the block declares no field with that id. Declare the field, or write it as a data-, aria- or html- attribute to put it on the root element.'=>'%2$s ब्लॉक टैग पर "%1$s" एट्रिब्यूट हटा दिहल जाला, काहे कि ब्लॉक में एह आईडी वाला कवनो फील्ड नइखे। फील्ड घोषित करीं, भा एकरा के data-, aria- चाहे html- एट्रिब्यूट के रूप में लिखीं, ताकि ई रूट एलिमेंट पर लागे।','This storage key is not declared by the block or its extensions.'=>'ई स्टोरेज कुंजी ब्लॉक भा ओकर एक्सटेंशन में घोषित नइखे।','This top-level key is not an attribute of the block, so it is ignored.'=>'ई ऊपर-स्तर के कुंजी ब्लॉक के गुण ना ह, एहसे एकरा अनदेखा कइल जाला।','This key is only read inside the blockstudio object, which is missing.'=>'ई कुंजी खाली blockstudio ऑब्जेक्ट के भीतर पढ़ल जाला, जे मौजूद नइखे।','This value is not among the field options.'=>'ई मान फील्ड के विकल्पन में नइखे।','This value has an unsupported shape for the field.'=>'ई मान के बनावट फील्ड खातिर समर्थित नइखे।','This repeater has fewer rows than its minimum.'=>'एह रिपीटर में न्यूनतम से कम पंक्ति बा।','This repeater has more rows than its maximum.'=>'एह रिपीटर में अधिकतम से बेसी पंक्ति बा।','This storage key has conflicting field definitions.'=>'एह स्टोरेज कुंजी खातिर फील्ड के परस्पर विरोधी परिभाषा बा।','The nested field value overrides this top-level value.'=>'नेस्टेड फील्ड के मान एह सबसे ऊपर वाला मान के बदल देला।','Extension bindings read this value only from blockstudio.attributes.'=>'एक्सटेंशन बाइंडिंग एह मान के खाली blockstudio.attributes से पढ़ेला।','Blockstudio field values must be stored in an object.'=>'Blockstudio फील्ड के मान ऑब्जेक्ट में रखल जरूरी बा।','Blockstudio is preparing its block cache. Please retry shortly.'=>'Blockstudio अपना ब्लॉक कैश तैयार करत बा। कुछ द